insert into public.destinos (id, nombre, slug, tipo, pais, region, continente, ubicacion, resumen, descripcion, imagen, galeria, categoria, actividades, lugares, clima, creditos, destacado, estado) values
(1, 'Cartagena', 'cartagena', 'nacional', 'Colombia', 'Caribe colombiano', 'América', 'Bolívar, Colombia', 'Ciudad amurallada, balcones floridos y atardeceres frente al mar Caribe.', 'Cartagena de Indias combina historia colonial, gastronomía y playas cercanas. Su centro histórico, declarado Patrimonio de la Humanidad por la UNESCO, invita a recorrer calles coloridas, plazas y murallas, mientras las islas cercanas ofrecen aguas cristalinas para descansar.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a1/Front_of_Cartagena_Colombia_Old_Town_Cathedral.jpg/1920px-Front_of_Cartagena_Colombia_Old_Town_Cathedral.jpg', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a1/Front_of_Cartagena_Colombia_Old_Town_Cathedral.jpg/1920px-Front_of_Cartagena_Colombia_Old_Town_Cathedral.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8e/Cartagena_Colombia_Old_Town_FishTail_Palm_Fruit.jpg/1920px-Cartagena_Colombia_Old_Town_FishTail_Palm_Fruit.jpg', 'https://upload.wikimedia.org/wikipedia/commons/f/f2/Cartagena%2C_Colombia_%285049256137%29.jpg_unscaled', 'https://upload.wikimedia.org/wikipedia/commons/0/07/Cartagena_old_town.JPG_unscaled', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/30/Museo_Naval_del_Caribe.JPG/1920px-Museo_Naval_del_Caribe.JPG']::text[], array['playa', 'cultural', 'romantico']::text[], array['Recorrido por la ciudad amurallada', 'Paseo a Islas del Rosario', 'Tour en chiva rumbera', 'Atardecer en las murallas', 'Visita a Playa Blanca (Barú)']::text[], array['Centro histórico', 'Castillo San Felipe de Barajas', 'Barrio Getsemaní', 'Islas del Rosario', 'Bocagrande']::text[], 'Cálido tropical durante todo el año, con temperaturas que suelen estar entre 25 °C y 32 °C.', '[{"titulo":"Front of Cartagena Colombia Old Town Cathedral.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Front_of_Cartagena_Colombia_Old_Town_Cathedral.jpg"},{"titulo":"Cartagena Colombia Old Town FishTail Palm Fruit.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Cartagena_Colombia_Old_Town_FishTail_Palm_Fruit.jpg"},{"titulo":"Cartagena, Colombia (5049256137).jpg","fuente":"https://commons.wikimedia.org/wiki/File:Cartagena,_Colombia_(5049256137).jpg"},{"titulo":"Cartagena old town.JPG","fuente":"https://commons.wikimedia.org/wiki/File:Cartagena_old_town.JPG"},{"titulo":"Museo Naval del Caribe.JPG","fuente":"https://commons.wikimedia.org/wiki/File:Museo_Naval_del_Caribe.JPG"}]'::jsonb, true, 'activo'),
(2, 'Santa Marta', 'santa-marta', 'nacional', 'Colombia', 'Caribe colombiano', 'América', 'Magdalena, Colombia', 'Donde la Sierra Nevada se encuentra con el mar Caribe.', 'Santa Marta es una de las ciudades más antiguas de Colombia y puerta de entrada a la Sierra Nevada, el Parque Tayrona y Minca. Es ideal para combinar playa, naturaleza y cultura en un mismo viaje.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/55/Bah%C3%ADa_de_Santa_Marta.jpg/1920px-Bah%C3%ADa_de_Santa_Marta.jpg', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/5/55/Bah%C3%ADa_de_Santa_Marta.jpg/1920px-Bah%C3%ADa_de_Santa_Marta.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2b/Bahia_de_Santa_Marta_04.JPG/1920px-Bahia_de_Santa_Marta_04.JPG', 'https://upload.wikimedia.org/wikipedia/commons/2/2a/Santa_Marta_Bahia.jpg_unscaled', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1b/Bah%C3%ADa_de_Santa_Marta_vista_desde_chalupa.jpg/1920px-Bah%C3%ADa_de_Santa_Marta_vista_desde_chalupa.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1c/Colombia_bahia_de_Santa_Marta.JPG/1920px-Colombia_bahia_de_Santa_Marta.JPG']::text[], array['playa', 'naturaleza', 'familiar']::text[], array['Tour a Minca y sus cascadas', 'Visita al Parque Tayrona', 'Playas de Taganga y Rodadero', 'Avistamiento de aves']::text[], array['Centro histórico', 'Quinta de San Pedro Alejandrino', 'Minca', 'El Rodadero', 'Taganga']::text[], 'Cálido y seco la mayor parte del año, con temperaturas habituales entre 27 °C y 33 °C.', '[{"titulo":"Bahía de Santa Marta.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Bah%C3%ADa_de_Santa_Marta.jpg"},{"titulo":"Bahia de Santa Marta 04.JPG","fuente":"https://commons.wikimedia.org/wiki/File:Bahia_de_Santa_Marta_04.JPG"},{"titulo":"Santa Marta Bahia.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Santa_Marta_Bahia.jpg"},{"titulo":"Bahía de Santa Marta vista desde chalupa.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Bah%C3%ADa_de_Santa_Marta_vista_desde_chalupa.jpg"},{"titulo":"Colombia bahia de Santa Marta.JPG","fuente":"https://commons.wikimedia.org/wiki/File:Colombia_bahia_de_Santa_Marta.JPG"}]'::jsonb, true, 'activo'),
(3, 'San Andrés', 'san-andres', 'nacional', 'Colombia', 'Caribe colombiano', 'América', 'Archipiélago de San Andrés, Providencia y Santa Catalina', 'El mar de los siete colores en una isla para disfrutar sin prisa.', 'San Andrés es famosa por su mar de tonos turquesa, sus cayos y su cultura raizal. Es un destino perfecto para descansar, practicar snorkel y recorrer la isla en mula o carrito de golf.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d3/Atardecer_en_San_Andres_Isla.JPG/1920px-Atardecer_en_San_Andres_Isla.JPG', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d3/Atardecer_en_San_Andres_Isla.JPG/1920px-Atardecer_en_San_Andres_Isla.JPG', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6d/Uninhabited_island_Cayo_Bolivar.jpg/1920px-Uninhabited_island_Cayo_Bolivar.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/Punta_Sur_%288330405067%29.jpg/1920px-Punta_Sur_%288330405067%29.jpg', 'https://upload.wikimedia.org/wikipedia/commons/e/e3/San_Andres_Island_Montage.jpg_unscaled']::text[], array['playa', 'familiar', 'romantico']::text[], array['Tour a Johnny Cay y el Acuario', 'Snorkel y buceo', 'Vuelta a la isla', 'Visita a la Piscinita y West View']::text[], array['Johnny Cay', 'Cayo Acuario', 'Hoyo Soplador', 'Spratt Bight', 'La Piscinita']::text[], 'Cálido tropical, con temperaturas cercanas a 27 °C – 30 °C casi todo el año.', '[{"titulo":"Atardecer en San Andres Isla.JPG","fuente":"https://commons.wikimedia.org/wiki/File:Atardecer_en_San_Andres_Isla.JPG"},{"titulo":"Uninhabited island Cayo Bolivar.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Uninhabited_island_Cayo_Bolivar.jpg"},{"titulo":"Punta Sur (8330405067).jpg","fuente":"https://commons.wikimedia.org/wiki/File:Punta_Sur_(8330405067).jpg"},{"titulo":"San Andres Island Montage.jpg","fuente":"https://commons.wikimedia.org/wiki/File:San_Andres_Island_Montage.jpg"}]'::jsonb, true, 'activo'),
(4, 'La Guajira', 'la-guajira', 'nacional', 'Colombia', 'Caribe colombiano', 'América', 'La Guajira, Colombia', 'Desierto, dunas y mar en el extremo norte de Suramérica.', 'La Guajira ofrece paisajes únicos donde el desierto se encuentra con el mar. Es tierra del pueblo wayuu y escenario de experiencias como el Cabo de la Vela y Punta Gallinas.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dc/Cabo_de_la_Vela%2C_Colombia.jpg/1920px-Cabo_de_la_Vela%2C_Colombia.jpg', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dc/Cabo_de_la_Vela%2C_Colombia.jpg/1920px-Cabo_de_la_Vela%2C_Colombia.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fb/Manaure_paisajes_guajira_colombia_caminos_036896.JPG/1920px-Manaure_paisajes_guajira_colombia_caminos_036896.JPG', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4a/Manaure_paisajes_guajira_colombia_caminos_031678.JPG/1920px-Manaure_paisajes_guajira_colombia_caminos_031678.JPG', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/69/Manaure_paisajes_guajira_colombia_caminos_0798231.JPG/1920px-Manaure_paisajes_guajira_colombia_caminos_0798231.JPG', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0c/Guajira_20160121_Medano_Alewouru.jpg/1920px-Guajira_20160121_Medano_Alewouru.jpg']::text[], array['aventura', 'naturaleza', 'cultural']::text[], array['Expedición a Punta Gallinas', 'Atardecer en el Cabo de la Vela', 'Visita a rancherías wayuu', 'Paseo por las dunas de Taroa']::text[], array['Cabo de la Vela', 'Punta Gallinas', 'Dunas de Taroa', 'Riohacha', 'Pilón de Azúcar']::text[], 'Cálido y seco, con vientos constantes y temperaturas que pueden superar los 30 °C.', '[{"titulo":"Cabo de la Vela, Colombia.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Cabo_de_la_Vela,_Colombia.jpg"},{"titulo":"Manaure paisajes guajira colombia caminos 036896.JPG","fuente":"https://commons.wikimedia.org/wiki/File:Manaure_paisajes_guajira_colombia_caminos_036896.JPG"},{"titulo":"Manaure paisajes guajira colombia caminos 031678.JPG","fuente":"https://commons.wikimedia.org/wiki/File:Manaure_paisajes_guajira_colombia_caminos_031678.JPG"},{"titulo":"Manaure paisajes guajira colombia caminos 0798231.JPG","fuente":"https://commons.wikimedia.org/wiki/File:Manaure_paisajes_guajira_colombia_caminos_0798231.JPG"},{"titulo":"Guajira 20160121 Medano Alewouru.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Guajira_20160121_Medano_Alewouru.jpg"}]'::jsonb, false, 'activo'),
(5, 'Palomino', 'palomino', 'nacional', 'Colombia', 'Caribe colombiano', 'América', 'La Guajira, Colombia', 'Playas tranquilas y tubing por el río que baja de la Sierra Nevada.', 'Palomino es un pequeño pueblo costero rodeado de naturaleza, donde el río del mismo nombre desemboca en el mar. Es un destino tranquilo para desconectarse y vivir experiencias al aire libre.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0f/Palomino_beach.JPG/1920px-Palomino_beach.JPG', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0f/Palomino_beach.JPG/1920px-Palomino_beach.JPG', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5a/Palomino%2C_Kolumbien_%2812976665134%29.jpg/1920px-Palomino%2C_Kolumbien_%2812976665134%29.jpg']::text[], array['playa', 'naturaleza', 'aventura']::text[], array['Tubing por el río Palomino', 'Caminatas por la selva', 'Yoga y descanso frente al mar']::text[], array['Desembocadura del río Palomino', 'Playa de Palomino', 'Sierra Nevada de Santa Marta']::text[], 'Cálido tropical, con temperaturas habituales entre 25 °C y 32 °C.', '[{"titulo":"Palomino beach.JPG","fuente":"https://commons.wikimedia.org/wiki/File:Palomino_beach.JPG"},{"titulo":"Palomino, Kolumbien (12976665134).jpg","fuente":"https://commons.wikimedia.org/wiki/File:Palomino,_Kolumbien_(12976665134).jpg"}]'::jsonb, false, 'activo'),
(6, 'Parque Tayrona', 'parque-tayrona', 'nacional', 'Colombia', 'Caribe colombiano', 'América', 'Magdalena, Colombia', 'Playas vírgenes, selva tropical y senderos ancestrales.', 'El Parque Nacional Natural Tayrona protege playas, bosques y vestigios de la cultura tayrona. Sus senderos conducen a lugares emblemáticos como Cabo San Juan y Arrecifes. Tiene cierres temporales a lo largo del año, por lo que conviene planear con anticipación.', 'https://upload.wikimedia.org/wikipedia/commons/f/fe/Arrecifes.jpg_unscaled', array['https://upload.wikimedia.org/wikipedia/commons/f/fe/Arrecifes.jpg_unscaled', 'https://upload.wikimedia.org/wikipedia/commons/a/a6/Tayrona_02.jpg_unscaled', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/91/Tayrona_Beach.jpg/1920px-Tayrona_Beach.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c3/Tayrona_6.JPG/1920px-Tayrona_6.JPG', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ad/116_Tayrona_Colombia_Beach.JPG/1920px-116_Tayrona_Colombia_Beach.JPG']::text[], array['naturaleza', 'playa', 'aventura']::text[], array['Caminata a Cabo San Juan', 'Snorkel en La Piscina', 'Visita a Pueblito', 'Acampar o dormir en ecohabs']::text[], array['Cabo San Juan del Guía', 'Arrecifes', 'La Piscina', 'Playa Cristal', 'Pueblito']::text[], 'Cálido y húmedo, con temperaturas entre 25 °C y 32 °C.', '[{"titulo":"Arrecifes.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Arrecifes.jpg"},{"titulo":"Tayrona 02.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Tayrona_02.jpg"},{"titulo":"Tayrona Beach.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Tayrona_Beach.jpg"},{"titulo":"Tayrona 6.JPG","fuente":"https://commons.wikimedia.org/wiki/File:Tayrona_6.JPG"},{"titulo":"116 Tayrona Colombia Beach.JPG","fuente":"https://commons.wikimedia.org/wiki/File:116_Tayrona_Colombia_Beach.JPG"}]'::jsonb, true, 'activo'),
(7, 'Medellín', 'medellin', 'nacional', 'Colombia', 'Antioquia', 'América', 'Antioquia, Colombia', 'La ciudad de la eterna primavera, innovadora y llena de vida.', 'Medellín es reconocida por su clima agradable, su transformación urbana y la calidez de su gente. Sus metrocables, parques, museos y miradores muestran una ciudad vibrante rodeada de montañas.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/76/Centro_de_Medell%C3%ADn_en_dron_04.jpg/1920px-Centro_de_Medell%C3%ADn_en_dron_04.jpg', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/7/76/Centro_de_Medell%C3%ADn_en_dron_04.jpg/1920px-Centro_de_Medell%C3%ADn_en_dron_04.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a2/Metrocable_cabin_high_over_Medell%C3%ADn.jpg/1920px-Metrocable_cabin_high_over_Medell%C3%ADn.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/93/City_of_Medellin%2C_Antioquia%2C_Colombia.jpg/1920px-City_of_Medellin%2C_Antioquia%2C_Colombia.jpg']::text[], array['ciudad', 'cultural', 'gastronomia']::text[], array['Recorrido por la Comuna 13', 'Paseo en metrocable al Parque Arví', 'Tour de café y gastronomía', 'Visita a museos y plazas']::text[], array['Plaza Botero', 'Comuna 13', 'Parque Arví', 'Pueblito Paisa', 'Jardín Botánico']::text[], 'Templado y primaveral, con temperaturas habituales entre 17 °C y 28 °C.', '[{"titulo":"Centro de Medellín en dron 04.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Centro_de_Medell%C3%ADn_en_dron_04.jpg"},{"titulo":"Metrocable cabin high over Medellín.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Metrocable_cabin_high_over_Medell%C3%ADn.jpg"},{"titulo":"City of Medellin, Antioquia, Colombia.jpg","fuente":"https://commons.wikimedia.org/wiki/File:City_of_Medellin,_Antioquia,_Colombia.jpg"}]'::jsonb, true, 'activo'),
(8, 'Guatapé', 'guatape', 'nacional', 'Colombia', 'Antioquia', 'América', 'Antioquia, Colombia', 'Zócalos de colores y la vista inolvidable desde la Piedra del Peñol.', 'Guatapé es un pueblo lleno de color junto a un gran embalse. Subir los escalones de la Piedra del Peñol y navegar entre sus islas son experiencias imprescindibles a pocas horas de Medellín.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/55/Colombia-Guatape-Fachadas_02.jpg/1920px-Colombia-Guatape-Fachadas_02.jpg', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/5/55/Colombia-Guatape-Fachadas_02.jpg/1920px-Colombia-Guatape-Fachadas_02.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/98/Colombia-Guatape-Fachadas_01.jpg/1920px-Colombia-Guatape-Fachadas_01.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1e/Colombia-Guatape-Fachadas_03.jpg/1920px-Colombia-Guatape-Fachadas_03.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b3/Guatape.jpg/1920px-Guatape.jpg', 'https://upload.wikimedia.org/wikipedia/commons/9/99/Embalse_Pe%C3%B1ol-Guatape.jpg_unscaled']::text[], array['naturaleza', 'familiar', 'aventura']::text[], array['Ascenso a la Piedra del Peñol', 'Paseo en lancha por el embalse', 'Recorrido por los zócalos', 'Deportes náuticos']::text[], array['Piedra del Peñol', 'Calle de los Recuerdos', 'Malecón de Guatapé', 'Embalse Peñol-Guatapé']::text[], 'Templado, con temperaturas entre 16 °C y 26 °C.', '[{"titulo":"Colombia-Guatape-Fachadas 02.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Colombia-Guatape-Fachadas_02.jpg"},{"titulo":"Colombia-Guatape-Fachadas 01.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Colombia-Guatape-Fachadas_01.jpg"},{"titulo":"Colombia-Guatape-Fachadas 03.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Colombia-Guatape-Fachadas_03.jpg"},{"titulo":"Guatape.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Guatape.jpg"},{"titulo":"Embalse Peñol-Guatape.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Embalse_Pe%C3%B1ol-Guatape.jpg"}]'::jsonb, true, 'activo'),
(9, 'Jardín', 'jardin', 'nacional', 'Colombia', 'Antioquia', 'América', 'Suroeste antioqueño, Colombia', 'Un pueblo patrimonio rodeado de montañas cafeteras y cascadas.', 'Jardín conserva la arquitectura tradicional antioqueña con balcones coloridos y una imponente basílica. Sus alrededores ofrecen cascadas, cuevas y fincas cafeteras.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c7/Panor%C3%A1mica_de_Jard%C3%ADn%2C_Antioquia%2C_2022.jpg/1920px-Panor%C3%A1mica_de_Jard%C3%ADn%2C_Antioquia%2C_2022.jpg', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c7/Panor%C3%A1mica_de_Jard%C3%ADn%2C_Antioquia%2C_2022.jpg/1920px-Panor%C3%A1mica_de_Jard%C3%ADn%2C_Antioquia%2C_2022.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/39/Fachadas_de_casa-Jardin_antioquia_1.jpg/1920px-Fachadas_de_casa-Jardin_antioquia_1.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b8/Fachadas_jardin_-antioquia.jpg/1920px-Fachadas_jardin_-antioquia.jpg']::text[], array['naturaleza', 'cultural', 'romantico']::text[], array['Visita a la Cueva del Esplendor', 'Paseo en garrucha', 'Tour de café', 'Avistamiento del gallito de roca']::text[], array['Basílica de la Inmaculada Concepción', 'Cueva del Esplendor', 'Cerro Cristo Rey', 'Charco Corazón']::text[], 'Templado de montaña, entre 15 °C y 24 °C.', '[{"titulo":"Panorámica de Jardín, Antioquia, 2022.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Panor%C3%A1mica_de_Jard%C3%ADn,_Antioquia,_2022.jpg"},{"titulo":"Fachadas de casa-Jardin antioquia 1.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Fachadas_de_casa-Jardin_antioquia_1.jpg"},{"titulo":"Fachadas jardin -antioquia.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Fachadas_jardin_-antioquia.jpg"}]'::jsonb, false, 'activo'),
(10, 'Santa Fe de Antioquia', 'santa-fe-de-antioquia', 'nacional', 'Colombia', 'Antioquia', 'América', 'Occidente antioqueño, Colombia', 'Calles empedradas, historia colonial y clima cálido.', 'Santa Fe de Antioquia fue capital de la provincia y conserva un centro histórico de casonas coloniales. Es un plan ideal de descanso con piscina y cultura, cerca de Medellín.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5d/SANTA_FE_DE_ANTIOQUIA-4.jpg/1920px-SANTA_FE_DE_ANTIOQUIA-4.jpg', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5d/SANTA_FE_DE_ANTIOQUIA-4.jpg/1920px-SANTA_FE_DE_ANTIOQUIA-4.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/63/Callecita._Santa_Fe_de_Antioquia_%28antioquia%29._Colombia.JPG/1920px-Callecita._Santa_Fe_de_Antioquia_%28antioquia%29._Colombia.JPG', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/84/CALLE_ENTRADA._Santa_Fe_de_Antioquia_%28antioquia%29._Colombia.JPG/1920px-CALLE_ENTRADA._Santa_Fe_de_Antioquia_%28antioquia%29._Colombia.JPG', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3d/Perspectiva_calle_1._Santa_Fe_de_Antioquia_%28antioquia%29._Colombia.JPG/1920px-Perspectiva_calle_1._Santa_Fe_de_Antioquia_%28antioquia%29._Colombia.JPG', 'https://upload.wikimedia.org/wikipedia/commons/4/4c/Santa_Fe_de_Antioquia_2.JPG_unscaled']::text[], array['cultural', 'familiar']::text[], array['Recorrido por el centro histórico', 'Visita al Puente de Occidente', 'Descanso en hoteles campestres']::text[], array['Puente de Occidente', 'Catedral Basílica', 'Plaza Mayor', 'Museo Juan del Corral']::text[], 'Cálido, con temperaturas que suelen estar entre 24 °C y 34 °C.', '[{"titulo":"SANTA FE DE ANTIOQUIA-4.jpg","fuente":"https://commons.wikimedia.org/wiki/File:SANTA_FE_DE_ANTIOQUIA-4.jpg"},{"titulo":"Callecita. Santa Fe de Antioquia (antioquia). Colombia.JPG","fuente":"https://commons.wikimedia.org/wiki/File:Callecita._Santa_Fe_de_Antioquia_(antioquia)._Colombia.JPG"},{"titulo":"CALLE ENTRADA. Santa Fe de Antioquia (antioquia). Colombia.JPG","fuente":"https://commons.wikimedia.org/wiki/File:CALLE_ENTRADA._Santa_Fe_de_Antioquia_(antioquia)._Colombia.JPG"},{"titulo":"Perspectiva calle 1. Santa Fe de Antioquia (antioquia). Colombia.JPG","fuente":"https://commons.wikimedia.org/wiki/File:Perspectiva_calle_1._Santa_Fe_de_Antioquia_(antioquia)._Colombia.JPG"},{"titulo":"Santa Fe de Antioquia 2.JPG","fuente":"https://commons.wikimedia.org/wiki/File:Santa_Fe_de_Antioquia_2.JPG"}]'::jsonb, false, 'activo'),
(11, 'Salento', 'salento', 'nacional', 'Colombia', 'Eje Cafetero', 'América', 'Quindío, Colombia', 'El pueblo más tradicional del Paisaje Cultural Cafetero.', 'Salento es famoso por sus casas de colores, su artesanía y su cercanía al Valle del Cocora. Es la base perfecta para conocer fincas cafeteras y paisajes de montaña.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7b/View_of_Salento%2C_Colombia_01.jpg/1920px-View_of_Salento%2C_Colombia_01.jpg', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7b/View_of_Salento%2C_Colombia_01.jpg/1920px-View_of_Salento%2C_Colombia_01.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/ba/Salento%2C_R%C3%ADo_Quind%C3%ADo%2C_2023-07_CN-02.jpg/1920px-Salento%2C_R%C3%ADo_Quind%C3%ADo%2C_2023-07_CN-02.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ac/Salento%2C_R%C3%ADo_Quind%C3%ADo%2C_2023-07_CN-01.jpg/1920px-Salento%2C_R%C3%ADo_Quind%C3%ADo%2C_2023-07_CN-01.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/71/Calle_5%2C_Salento_01.jpg/1920px-Calle_5%2C_Salento_01.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8c/Calle_5%2C_Salento_02.jpg/1920px-Calle_5%2C_Salento_02.jpg']::text[], array['naturaleza', 'cultural', 'familiar']::text[], array['Tour de café en finca', 'Caminata al Valle del Cocora', 'Recorrido por la Calle Real', 'Mirador de Salento']::text[], array['Calle Real', 'Mirador Alto de la Cruz', 'Fincas cafeteras', 'Valle del Cocora']::text[], 'Templado de montaña, entre 14 °C y 24 °C.', '[{"titulo":"View of Salento, Colombia 01.jpg","fuente":"https://commons.wikimedia.org/wiki/File:View_of_Salento,_Colombia_01.jpg"},{"titulo":"Salento, Río Quindío, 2023-07 CN-02.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Salento,_R%C3%ADo_Quind%C3%ADo,_2023-07_CN-02.jpg"},{"titulo":"Salento, Río Quindío, 2023-07 CN-01.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Salento,_R%C3%ADo_Quind%C3%ADo,_2023-07_CN-01.jpg"},{"titulo":"Calle 5, Salento 01.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Calle_5,_Salento_01.jpg"},{"titulo":"Calle 5, Salento 02.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Calle_5,_Salento_02.jpg"}]'::jsonb, true, 'activo'),
(12, 'Pereira', 'pereira', 'nacional', 'Colombia', 'Eje Cafetero', 'América', 'Risaralda, Colombia', 'Ciudad cafetera, puerta de termales y paisajes verdes.', 'Pereira es un punto estratégico para explorar el Eje Cafetero. Desde allí se accede a termales, parques temáticos y reservas naturales.', 'https://upload.wikimedia.org/wikipedia/commons/1/12/Skyline_Pereira.jpg_unscaled', array['https://upload.wikimedia.org/wikipedia/commons/1/12/Skyline_Pereira.jpg_unscaled', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/91/Pereira%2C_Coloimbia.jpg/1920px-Pereira%2C_Coloimbia.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/12/Alto_del_Nudo_-_Pereira.jpg/1920px-Alto_del_Nudo_-_Pereira.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Pereira-Cultural.jpg/1920px-Pereira-Cultural.jpg', 'https://upload.wikimedia.org/wikipedia/commons/e/e6/Carrera_10_Pereira_-_panoramio.jpg_unscaled']::text[], array['ciudad', 'naturaleza', 'familiar']::text[], array['Visita a termales de Santa Rosa de Cabal', 'Parque Ukumarí', 'Tour de café', 'Recorrido urbano']::text[], array['Termales de Santa Rosa', 'Plaza de Bolívar', 'Parque Ukumarí', 'Viaducto César Gaviria Trujillo']::text[], 'Templado, con temperaturas entre 17 °C y 27 °C.', '[{"titulo":"Skyline Pereira.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Skyline_Pereira.jpg"},{"titulo":"Pereira, Coloimbia.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Pereira,_Coloimbia.jpg"},{"titulo":"Alto del Nudo - Pereira.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Alto_del_Nudo_-_Pereira.jpg"},{"titulo":"Pereira-Cultural.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Pereira-Cultural.jpg"},{"titulo":"Carrera 10 Pereira - panoramio.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Carrera_10_Pereira_-_panoramio.jpg"}]'::jsonb, false, 'activo'),
(13, 'Armenia', 'armenia', 'nacional', 'Colombia', 'Eje Cafetero', 'América', 'Quindío, Colombia', 'Parques temáticos y cultura cafetera para toda la familia.', 'Armenia, capital del Quindío, está rodeada de parques temáticos, fincas y pueblos tradicionales. Es un destino muy apreciado por familias.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/52/Armenia%2C_Quindio%2C_Colombia_-_panoramio_-_Jimmy_G%C3%B3mez_N_%285%29.jpg/1920px-Armenia%2C_Quindio%2C_Colombia_-_panoramio_-_Jimmy_G%C3%B3mez_N_%285%29.jpg', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/5/52/Armenia%2C_Quindio%2C_Colombia_-_panoramio_-_Jimmy_G%C3%B3mez_N_%285%29.jpg/1920px-Armenia%2C_Quindio%2C_Colombia_-_panoramio_-_Jimmy_G%C3%B3mez_N_%285%29.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/54/Armenia%2C_Quindio%2C_Colombia.jpg/1920px-Armenia%2C_Quindio%2C_Colombia.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/90/Armenia%2C_Quindio%2C_Colombia_-_panoramio_-_Jimmy_G%C3%B3mez_N_%2815%29.jpg/1920px-Armenia%2C_Quindio%2C_Colombia_-_panoramio_-_Jimmy_G%C3%B3mez_N_%2815%29.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/65/Armenia%2C_Quindio%2C_Colombia_-_panoramio_-_Jimmy_G%C3%B3mez_N_%2816%29.jpg/1920px-Armenia%2C_Quindio%2C_Colombia_-_panoramio_-_Jimmy_G%C3%B3mez_N_%2816%29.jpg']::text[], array['familiar', 'naturaleza', 'cultural']::text[], array['Parque del Café', 'Panaca', 'Jardín Botánico del Quindío y mariposario', 'Visita a Filandia']::text[], array['Parque del Café', 'Panaca', 'Jardín Botánico del Quindío', 'Filandia']::text[], 'Templado, con temperaturas entre 17 °C y 27 °C.', '[{"titulo":"Armenia, Quindio, Colombia - panoramio - Jimmy Gómez N (5).jpg","fuente":"https://commons.wikimedia.org/wiki/File:Armenia,_Quindio,_Colombia_-_panoramio_-_Jimmy_G%C3%B3mez_N_(5).jpg"},{"titulo":"Armenia, Quindio, Colombia.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Armenia,_Quindio,_Colombia.jpg"},{"titulo":"Armenia, Quindio, Colombia - panoramio - Jimmy Gómez N (15).jpg","fuente":"https://commons.wikimedia.org/wiki/File:Armenia,_Quindio,_Colombia_-_panoramio_-_Jimmy_G%C3%B3mez_N_(15).jpg"},{"titulo":"Armenia, Quindio, Colombia - panoramio - Jimmy Gómez N (16).jpg","fuente":"https://commons.wikimedia.org/wiki/File:Armenia,_Quindio,_Colombia_-_panoramio_-_Jimmy_G%C3%B3mez_N_(16).jpg"}]'::jsonb, false, 'activo'),
(14, 'Valle del Cocora', 'valle-del-cocora', 'nacional', 'Colombia', 'Eje Cafetero', 'América', 'Salento, Quindío, Colombia', 'Las palmas de cera más altas del mundo entre montañas y niebla.', 'El Valle del Cocora es hogar de la palma de cera, árbol nacional de Colombia. Sus senderos atraviesan bosques de niebla, ríos y miradores con paisajes de postal.', 'https://upload.wikimedia.org/wikipedia/commons/c/cb/Valle_del_cocora_-_general_view.jpg_unscaled', array['https://upload.wikimedia.org/wikipedia/commons/c/cb/Valle_del_cocora_-_general_view.jpg_unscaled', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/af/Valle_de_Cocora%2C_Colombia_02.jpg/1920px-Valle_de_Cocora%2C_Colombia_02.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/40/Valle_de_Cocora%2C_Colombia_03.jpg/1920px-Valle_de_Cocora%2C_Colombia_03.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/00/Valle_de_Cocora%2C_Colombia_04.jpg/1920px-Valle_de_Cocora%2C_Colombia_04.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e4/Valle_del_cocora_-_wax_palm_02.jpg/1920px-Valle_del_cocora_-_wax_palm_02.jpg']::text[], array['naturaleza', 'aventura']::text[], array['Caminata por el valle', 'Cabalgata', 'Visita a la Casa de los Colibríes', 'Fotografía de paisaje']::text[], array['Bosque de palmas de cera', 'Acaime (Casa de los Colibríes)', 'Mirador La Montaña']::text[], 'Fresco de montaña, entre 10 °C y 20 °C; se recomienda llevar abrigo.', '[{"titulo":"Valle del cocora - general view.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Valle_del_cocora_-_general_view.jpg"},{"titulo":"Valle de Cocora, Colombia 02.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Valle_de_Cocora,_Colombia_02.jpg"},{"titulo":"Valle de Cocora, Colombia 03.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Valle_de_Cocora,_Colombia_03.jpg"},{"titulo":"Valle de Cocora, Colombia 04.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Valle_de_Cocora,_Colombia_04.jpg"},{"titulo":"Valle del cocora - wax palm 02.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Valle_del_cocora_-_wax_palm_02.jpg"}]'::jsonb, true, 'activo'),
(15, 'Bogotá', 'bogota', 'nacional', 'Colombia', 'Región Andina', 'América', 'Cundinamarca, Colombia', 'Capital cultural con museos, historia y gastronomía de primer nivel.', 'Bogotá ofrece museos de talla mundial, un centro histórico vibrante y una escena gastronómica diversa. Desde Monserrate se aprecia la inmensidad de la ciudad.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/14/Bogot%C3%A1%2C_Santa_Fe%2C_2023-06_CN-02.jpg/1920px-Bogot%C3%A1%2C_Santa_Fe%2C_2023-06_CN-02.jpg', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/1/14/Bogot%C3%A1%2C_Santa_Fe%2C_2023-06_CN-02.jpg/1920px-Bogot%C3%A1%2C_Santa_Fe%2C_2023-06_CN-02.jpg', 'https://upload.wikimedia.org/wikipedia/commons/4/41/La_Candelaria%2C_Bogota%2C_Colombia_%285818105341%29.jpg_unscaled', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/db/La_Candelaria_-_Casa_colonial_%28Bogot%C3%A1%29_02.JPG/1920px-La_Candelaria_-_Casa_colonial_%28Bogot%C3%A1%29_02.JPG', 'https://upload.wikimedia.org/wikipedia/commons/6/6e/Calle_del_Camarin_del_Carmen%2C_Barrio_La_Candelaria_%28Bogot%C3%A1%2C_Colombia%29_1.jpg_unscaled']::text[], array['ciudad', 'cultural', 'gastronomia']::text[], array['Subida a Monserrate', 'Recorrido por La Candelaria', 'Visita al Museo del Oro', 'Excursión a la Catedral de Sal de Zipaquirá']::text[], array['Monserrate', 'La Candelaria', 'Museo del Oro', 'Museo Botero', 'Usaquén']::text[], 'Frío de montaña, con temperaturas habituales entre 8 °C y 20 °C.', '[{"titulo":"Bogotá, Santa Fe, 2023-06 CN-02.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Bogot%C3%A1,_Santa_Fe,_2023-06_CN-02.jpg"},{"titulo":"La Candelaria, Bogota, Colombia (5818105341).jpg","fuente":"https://commons.wikimedia.org/wiki/File:La_Candelaria,_Bogota,_Colombia_(5818105341).jpg"},{"titulo":"La Candelaria - Casa colonial (Bogotá) 02.JPG","fuente":"https://commons.wikimedia.org/wiki/File:La_Candelaria_-_Casa_colonial_(Bogot%C3%A1)_02.JPG"},{"titulo":"Calle del Camarin del Carmen, Barrio La Candelaria (Bogotá, Colombia) 1.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Calle_del_Camarin_del_Carmen,_Barrio_La_Candelaria_(Bogot%C3%A1,_Colombia)_1.jpg"}]'::jsonb, false, 'activo'),
(16, 'Villa de Leyva', 'villa-de-leyva', 'nacional', 'Colombia', 'Región Andina', 'América', 'Boyacá, Colombia', 'Una de las plazas coloniales más grandes de Suramérica.', 'Villa de Leyva conserva su arquitectura colonial y sus calles empedradas. A su alrededor hay viñedos, pozos azules, fósiles y paisajes semidesérticos.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/16/Villa_de_Leyva_Boyaca_22.JPG/1920px-Villa_de_Leyva_Boyaca_22.JPG', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/1/16/Villa_de_Leyva_Boyaca_22.JPG/1920px-Villa_de_Leyva_Boyaca_22.JPG', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/14/Plaza_Mayor%2C_Villa_de_Leyva_02.jpg/1920px-Plaza_Mayor%2C_Villa_de_Leyva_02.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b3/Statue_of_Antonio_Ricaurte%2C_Villa_de_Leyva_01.jpg/1920px-Statue_of_Antonio_Ricaurte%2C_Villa_de_Leyva_01.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ce/Pila_de_agua_en_la_Plaza_Central_en_Villa_de_Leyva%2C_Boyac%C3%A1%2C_Colombia.jpg/1920px-Pila_de_agua_en_la_Plaza_Central_en_Villa_de_Leyva%2C_Boyac%C3%A1%2C_Colombia.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b0/Plaza_Central_o_Plaza_Principal%E2%80%94_Villa_de_Leyva%2C_Boyac%C3%A1%2C_Colombia.jpg/1920px-Plaza_Central_o_Plaza_Principal%E2%80%94_Villa_de_Leyva%2C_Boyac%C3%A1%2C_Colombia.jpg']::text[], array['cultural', 'romantico', 'familiar']::text[], array['Recorrido por la Plaza Mayor', 'Visita al Pozo Azul', 'Museo del Fósil', 'Casa Terracota']::text[], array['Plaza Mayor', 'Casa Terracota', 'Museo El Fósil', 'Pozos Azules']::text[], 'Templado y seco, entre 12 °C y 24 °C.', '[{"titulo":"Villa de Leyva Boyaca 22.JPG","fuente":"https://commons.wikimedia.org/wiki/File:Villa_de_Leyva_Boyaca_22.JPG"},{"titulo":"Plaza Mayor, Villa de Leyva 02.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Plaza_Mayor,_Villa_de_Leyva_02.jpg"},{"titulo":"Statue of Antonio Ricaurte, Villa de Leyva 01.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Statue_of_Antonio_Ricaurte,_Villa_de_Leyva_01.jpg"},{"titulo":"Pila de agua en la Plaza Central en Villa de Leyva, Boyacá, Colombia.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Pila_de_agua_en_la_Plaza_Central_en_Villa_de_Leyva,_Boyac%C3%A1,_Colombia.jpg"},{"titulo":"Plaza Central o Plaza Principal— Villa de Leyva, Boyacá, Colombia.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Plaza_Central_o_Plaza_Principal%E2%80%94_Villa_de_Leyva,_Boyac%C3%A1,_Colombia.jpg"}]'::jsonb, false, 'activo'),
(17, 'Santander', 'santander', 'nacional', 'Colombia', 'Región Andina', 'América', 'Santander, Colombia', 'Capital del turismo de aventura en Colombia.', 'Santander es tierra de cañones, ríos y deportes extremos. San Gil es el centro de actividades como rafting, parapente y torrentismo, mientras el Cañón del Chicamocha sorprende con su inmensidad.', 'https://upload.wikimedia.org/wikipedia/commons/e/e1/Sobrevolando_Colombia_-_En_ruta_hacia_Bucaramanga_%288204596774%29.jpg_unscaled', array['https://upload.wikimedia.org/wikipedia/commons/e/e1/Sobrevolando_Colombia_-_En_ruta_hacia_Bucaramanga_%288204596774%29.jpg_unscaled', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d9/Ca%C3%B1%C3%B3n_Del_Chicamocha.jpg/1920px-Ca%C3%B1%C3%B3n_Del_Chicamocha.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/83/Ca%C3%B1%C3%B3n_del_R%C3%ADo_Chicamocha_01.jpg/1920px-Ca%C3%B1%C3%B3n_del_R%C3%ADo_Chicamocha_01.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/15/Ca%C3%B1%C3%B3n_del_R%C3%ADo_Chicamocha_03.jpg/1920px-Ca%C3%B1%C3%B3n_del_R%C3%ADo_Chicamocha_03.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5a/Ca%C3%B1%C3%B3n_del_R%C3%ADo_Chicamocha_02.jpg/1920px-Ca%C3%B1%C3%B3n_del_R%C3%ADo_Chicamocha_02.jpg']::text[], array['aventura', 'naturaleza']::text[], array['Rafting en el río Fonce', 'Parapente en el Chicamocha', 'Torrentismo', 'Parque Nacional del Chicamocha']::text[], array['Cañón del Chicamocha', 'San Gil', 'Parque El Gallineral', 'Cascadas de Juan Curí']::text[], 'Variado según la zona; en San Gil suele estar entre 20 °C y 30 °C.', '[{"titulo":"Sobrevolando Colombia - En ruta hacia Bucaramanga (8204596774).jpg","fuente":"https://commons.wikimedia.org/wiki/File:Sobrevolando_Colombia_-_En_ruta_hacia_Bucaramanga_(8204596774).jpg"},{"titulo":"Cañón Del Chicamocha.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Ca%C3%B1%C3%B3n_Del_Chicamocha.jpg"},{"titulo":"Cañón del Río Chicamocha 01.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Ca%C3%B1%C3%B3n_del_R%C3%ADo_Chicamocha_01.jpg"},{"titulo":"Cañón del Río Chicamocha 03.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Ca%C3%B1%C3%B3n_del_R%C3%ADo_Chicamocha_03.jpg"},{"titulo":"Cañón del Río Chicamocha 02.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Ca%C3%B1%C3%B3n_del_R%C3%ADo_Chicamocha_02.jpg"}]'::jsonb, false, 'activo'),
(18, 'Barichara', 'barichara', 'nacional', 'Colombia', 'Región Andina', 'América', 'Santander, Colombia', 'Calles de piedra y casas de tapia en un pueblo detenido en el tiempo.', 'Barichara es uno de los pueblos más bellos de Colombia. Sus casas blancas, calles en piedra y el Camino Real hacia Guane lo convierten en un destino tranquilo y romántico.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a0/Street_in_Barichara_02.jpg/1920px-Street_in_Barichara_02.jpg', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a0/Street_in_Barichara_02.jpg/1920px-Street_in_Barichara_02.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/22/Catedral_de_La_Inmaculada_Concepci%C3%B3n_de_Barichara%2C_Santander.jpg/1920px-Catedral_de_La_Inmaculada_Concepci%C3%B3n_de_Barichara%2C_Santander.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ef/Iglesia_de_Barichara_%28Santander%29_-_vista_de_dron.jpg/1920px-Iglesia_de_Barichara_%28Santander%29_-_vista_de_dron.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3d/Barichara_panorama.jpg/1920px-Barichara_panorama.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3e/Barichara_artesanias.jpg/1920px-Barichara_artesanias.jpg']::text[], array['cultural', 'romantico']::text[], array['Caminata por el Camino Real a Guane', 'Recorrido por el pueblo', 'Talleres de papel artesanal']::text[], array['Camino Real', 'Mirador de Barichara', 'Catedral de la Inmaculada Concepción', 'Guane']::text[], 'Templado y seco, entre 18 °C y 28 °C.', '[{"titulo":"Street in Barichara 02.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Street_in_Barichara_02.jpg"},{"titulo":"Catedral de La Inmaculada Concepción de Barichara, Santander.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Catedral_de_La_Inmaculada_Concepci%C3%B3n_de_Barichara,_Santander.jpg"},{"titulo":"Iglesia de Barichara (Santander) - vista de dron.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Iglesia_de_Barichara_(Santander)_-_vista_de_dron.jpg"},{"titulo":"Barichara panorama.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Barichara_panorama.jpg"},{"titulo":"Barichara artesanias.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Barichara_artesanias.jpg"}]'::jsonb, false, 'activo'),
(19, 'Nuquí', 'nuqui', 'nacional', 'Colombia', 'Pacífico', 'América', 'Chocó, Colombia', 'Selva, mar y avistamiento de ballenas en el Pacífico.', 'Nuquí es un destino de naturaleza donde la selva llega hasta el mar. Entre julio y octubre es posible avistar ballenas jorobadas, además de disfrutar termales, cascadas y playas solitarias.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6b/SUNSET_BEACH_NUQUI_CHOCO_COLOMBIA_1.jpg/1920px-SUNSET_BEACH_NUQUI_CHOCO_COLOMBIA_1.jpg', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6b/SUNSET_BEACH_NUQUI_CHOCO_COLOMBIA_1.jpg/1920px-SUNSET_BEACH_NUQUI_CHOCO_COLOMBIA_1.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/58/SUNSET_BEACH_NUQUI_CHOCO_COLOMBIA_4.jpg/1920px-SUNSET_BEACH_NUQUI_CHOCO_COLOMBIA_4.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/64/SUNSET_BEACH_NUQUI_CHOCO_COLOMBIA_6.jpg/1920px-SUNSET_BEACH_NUQUI_CHOCO_COLOMBIA_6.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/19/SUNSET_BEACH_NUQUI_CHOCO_COLOMBIA_2.jpg/1920px-SUNSET_BEACH_NUQUI_CHOCO_COLOMBIA_2.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/45/SUNSET_BEACH_NUQUI_CHOCO_COLOMBIA_3.jpg/1920px-SUNSET_BEACH_NUQUI_CHOCO_COLOMBIA_3.jpg']::text[], array['naturaleza', 'aventura', 'playa']::text[], array['Avistamiento de ballenas (temporada)', 'Termales de Jurubirá', 'Caminatas por la selva', 'Surf']::text[], array['Playa Guachalito', 'Termales', 'Cascada del Amor', 'Parque Nacional Utría']::text[], 'Cálido y muy húmedo, con lluvias frecuentes durante el año.', '[{"titulo":"SUNSET BEACH NUQUI CHOCO COLOMBIA 1.jpg","fuente":"https://commons.wikimedia.org/wiki/File:SUNSET_BEACH_NUQUI_CHOCO_COLOMBIA_1.jpg"},{"titulo":"SUNSET BEACH NUQUI CHOCO COLOMBIA 4.jpg","fuente":"https://commons.wikimedia.org/wiki/File:SUNSET_BEACH_NUQUI_CHOCO_COLOMBIA_4.jpg"},{"titulo":"SUNSET BEACH NUQUI CHOCO COLOMBIA 6.jpg","fuente":"https://commons.wikimedia.org/wiki/File:SUNSET_BEACH_NUQUI_CHOCO_COLOMBIA_6.jpg"},{"titulo":"SUNSET BEACH NUQUI CHOCO COLOMBIA 2.jpg","fuente":"https://commons.wikimedia.org/wiki/File:SUNSET_BEACH_NUQUI_CHOCO_COLOMBIA_2.jpg"},{"titulo":"SUNSET BEACH NUQUI CHOCO COLOMBIA 3.jpg","fuente":"https://commons.wikimedia.org/wiki/File:SUNSET_BEACH_NUQUI_CHOCO_COLOMBIA_3.jpg"}]'::jsonb, false, 'activo'),
(20, 'Bahía Solano', 'bahia-solano', 'nacional', 'Colombia', 'Pacífico', 'América', 'Chocó, Colombia', 'Biodiversidad, buceo y playas rodeadas de selva.', 'Bahía Solano es un paraíso para los amantes de la naturaleza, con playas de arena oscura, cascadas y una gran biodiversidad marina. Es otro punto destacado para el avistamiento de ballenas.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/41/Mangrove_in_Bah%C3%ADa_Solano%2C_Choco%2C_Colombia.jpg/1920px-Mangrove_in_Bah%C3%ADa_Solano%2C_Choco%2C_Colombia.jpg', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/4/41/Mangrove_in_Bah%C3%ADa_Solano%2C_Choco%2C_Colombia.jpg/1920px-Mangrove_in_Bah%C3%ADa_Solano%2C_Choco%2C_Colombia.jpg']::text[], array['naturaleza', 'aventura']::text[], array['Avistamiento de ballenas (temporada)', 'Buceo', 'Pesca deportiva', 'Visita a cascadas']::text[], array['Playa El Almejal', 'Parque Nacional Utría', 'Cascada El Tigre']::text[], 'Cálido y húmedo, con lluvias frecuentes.', '[{"titulo":"Mangrove in Bahía Solano, Choco, Colombia.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Mangrove_in_Bah%C3%ADa_Solano,_Choco,_Colombia.jpg"}]'::jsonb, false, 'activo'),
(21, 'Buenaventura', 'buenaventura', 'nacional', 'Colombia', 'Pacífico', 'América', 'Valle del Cauca, Colombia', 'Puerta al Pacífico vallecaucano, con playas y sabores del mar.', 'Buenaventura es el principal puerto del Pacífico colombiano y punto de partida hacia playas como Juanchaco, Ladrilleros y La Bocana, además de experiencias de avistamiento de ballenas.', 'https://upload.wikimedia.org/wikipedia/commons/4/47/Buenaventura%2C_Colombia.jpg_unscaled', array['https://upload.wikimedia.org/wikipedia/commons/4/47/Buenaventura%2C_Colombia.jpg_unscaled', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ed/Colombia_Buenaventura_avond.JPG/1920px-Colombia_Buenaventura_avond.JPG', 'https://upload.wikimedia.org/wikipedia/commons/0/0c/Estaci%C3%B3n_de_Tren_de_Buenaventura_%28Valle_del_Cauca%29_Colombia_-Sur_Am%C3%A9rica-.JPG_unscaled']::text[], array['naturaleza', 'gastronomia']::text[], array['Paseo a Juanchaco y Ladrilleros', 'Avistamiento de ballenas (temporada)', 'Gastronomía del Pacífico']::text[], array['Juanchaco', 'Ladrilleros', 'La Bocana', 'Malecón Bahía de la Cruz']::text[], 'Cálido y húmedo, con lluvias frecuentes.', '[{"titulo":"Buenaventura, Colombia.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Buenaventura,_Colombia.jpg"},{"titulo":"Colombia Buenaventura avond.JPG","fuente":"https://commons.wikimedia.org/wiki/File:Colombia_Buenaventura_avond.JPG"},{"titulo":"Estación de Tren de Buenaventura (Valle del Cauca) Colombia -Sur América-.JPG","fuente":"https://commons.wikimedia.org/wiki/File:Estaci%C3%B3n_de_Tren_de_Buenaventura_(Valle_del_Cauca)_Colombia_-Sur_Am%C3%A9rica-.JPG"}]'::jsonb, false, 'activo'),
(22, 'Leticia', 'leticia', 'nacional', 'Colombia', 'Amazonía', 'América', 'Amazonas, Colombia', 'La puerta a la selva amazónica y al río más caudaloso del mundo.', 'Leticia está en la triple frontera entre Colombia, Brasil y Perú. Desde allí se navega el río Amazonas, se visitan comunidades indígenas y se vive la selva de cerca.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d0/Sunset_in_Leticia%2C_Amazonas%2C_Colombia_01.jpg/1920px-Sunset_in_Leticia%2C_Amazonas%2C_Colombia_01.jpg', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d0/Sunset_in_Leticia%2C_Amazonas%2C_Colombia_01.jpg/1920px-Sunset_in_Leticia%2C_Amazonas%2C_Colombia_01.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a0/Tabatinga_%28Brazil%29_and_Leticia_%28Colombia%29.jpg/1920px-Tabatinga_%28Brazil%29_and_Leticia_%28Colombia%29.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5d/Sunset_in_Leticia%2C_Amazonas%2C_Colombia_02.jpg/1920px-Sunset_in_Leticia%2C_Amazonas%2C_Colombia_02.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/15/Sunset_in_Leticia%2C_Amazonas%2C_Colombia_03.jpg/1920px-Sunset_in_Leticia%2C_Amazonas%2C_Colombia_03.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e1/Victoria_Regia_-_La_Milagrosa_-_Leticia%2C_Amazonas_Colombia_-_panoramio.jpg/1920px-Victoria_Regia_-_La_Milagrosa_-_Leticia%2C_Amazonas_Colombia_-_panoramio.jpg']::text[], array['naturaleza', 'aventura', 'cultural']::text[], array['Navegación por el río Amazonas', 'Avistamiento de delfines rosados', 'Visita a la Isla de los Micos', 'Caminatas por la selva']::text[], array['Río Amazonas', 'Isla de los Micos', 'Parque Santander', 'Lagos de Tarapoto']::text[], 'Cálido y húmedo, con temperaturas entre 24 °C y 32 °C.', '[{"titulo":"Sunset in Leticia, Amazonas, Colombia 01.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Sunset_in_Leticia,_Amazonas,_Colombia_01.jpg"},{"titulo":"Tabatinga (Brazil) and Leticia (Colombia).jpg","fuente":"https://commons.wikimedia.org/wiki/File:Tabatinga_(Brazil)_and_Leticia_(Colombia).jpg"},{"titulo":"Sunset in Leticia, Amazonas, Colombia 02.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Sunset_in_Leticia,_Amazonas,_Colombia_02.jpg"},{"titulo":"Sunset in Leticia, Amazonas, Colombia 03.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Sunset_in_Leticia,_Amazonas,_Colombia_03.jpg"},{"titulo":"Victoria Regia - La Milagrosa - Leticia, Amazonas Colombia - panoramio.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Victoria_Regia_-_La_Milagrosa_-_Leticia,_Amazonas_Colombia_-_panoramio.jpg"}]'::jsonb, true, 'activo'),
(23, 'Puerto Nariño', 'puerto-narino', 'nacional', 'Colombia', 'Amazonía', 'América', 'Amazonas, Colombia', 'Un pueblo amazónico sin carros, rodeado de lagos y selva.', 'Puerto Nariño es conocido como un pesebre natural por su tranquilidad y su compromiso ambiental. Es punto de partida hacia los lagos de Tarapoto.', 'https://upload.wikimedia.org/wikipedia/commons/d/db/Puerto_Narinno-Amazonas-Colombia.jpg_unscaled', array['https://upload.wikimedia.org/wikipedia/commons/d/db/Puerto_Narinno-Amazonas-Colombia.jpg_unscaled', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a4/Alcad%C3%ADa_de_Puerto_Nari%C3%B1o.JPG/1920px-Alcad%C3%ADa_de_Puerto_Nari%C3%B1o.JPG', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/30/Panorama_Puerto_Nari%C3%B1o%2C_Amazonas.jpg/1920px-Panorama_Puerto_Nari%C3%B1o%2C_Amazonas.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fc/Puerto_Nari%C3%B1o_Departamento_del_Amazonas.jpg/1920px-Puerto_Nari%C3%B1o_Departamento_del_Amazonas.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/49/Puerto_Nari%C3%B1o_banner.jpg/1920px-Puerto_Nari%C3%B1o_banner.jpg']::text[], array['naturaleza', 'cultural']::text[], array['Visita a los lagos de Tarapoto', 'Avistamiento de delfines', 'Recorrido por el pueblo', 'Mirador Naipata']::text[], array['Lagos de Tarapoto', 'Mirador Naipata', 'Fundación Natütama']::text[], 'Cálido y húmedo, con lluvias frecuentes.', '[{"titulo":"Puerto Narinno-Amazonas-Colombia.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Puerto_Narinno-Amazonas-Colombia.jpg"},{"titulo":"Alcadía de Puerto Nariño.JPG","fuente":"https://commons.wikimedia.org/wiki/File:Alcad%C3%ADa_de_Puerto_Nari%C3%B1o.JPG"},{"titulo":"Panorama Puerto Nariño, Amazonas.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Panorama_Puerto_Nari%C3%B1o,_Amazonas.jpg"},{"titulo":"Puerto Nariño Departamento del Amazonas.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Puerto_Nari%C3%B1o_Departamento_del_Amazonas.jpg"},{"titulo":"Puerto Nariño banner.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Puerto_Nari%C3%B1o_banner.jpg"}]'::jsonb, false, 'activo'),
(24, 'Villavicencio', 'villavicencio', 'nacional', 'Colombia', 'Llanos Orientales', 'América', 'Meta, Colombia', 'Cultura llanera, joropo y atardeceres infinitos.', 'Villavicencio es la puerta de entrada a los Llanos Orientales. Su cultura llanera, su gastronomía y sus paisajes de sabana son el atractivo principal.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0e/Villavicencio%2C_Meta%2C_Colombia_-_panoramio.jpg/1920px-Villavicencio%2C_Meta%2C_Colombia_-_panoramio.jpg', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0e/Villavicencio%2C_Meta%2C_Colombia_-_panoramio.jpg/1920px-Villavicencio%2C_Meta%2C_Colombia_-_panoramio.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8e/Villavicencio%2C_Meta%2C_Colombia_-_panoramio_%284%29.jpg/1920px-Villavicencio%2C_Meta%2C_Colombia_-_panoramio_%284%29.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d3/Villavicencio%2C_Meta%2C_Colombia_-_panoramio_%282%29.jpg/1920px-Villavicencio%2C_Meta%2C_Colombia_-_panoramio_%282%29.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7e/Villavicencio%2C_Meta%2C_Colombia_-_panoramio_%287%29.jpg/1920px-Villavicencio%2C_Meta%2C_Colombia_-_panoramio_%287%29.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/ba/Villavicencio%2C_Meta%2C_Colombia_-_panoramio_%281%29.jpg/1920px-Villavicencio%2C_Meta%2C_Colombia_-_panoramio_%281%29.jpg']::text[], array['naturaleza', 'cultural', 'gastronomia']::text[], array['Bioparque Los Ocarros', 'Experiencia de cultura llanera', 'Ruta del Amor Patrio', 'Gastronomía: mamona']::text[], array['Bioparque Los Ocarros', 'Parque Las Malocas', 'Catedral de Nuestra Señora del Carmen']::text[], 'Cálido, con temperaturas entre 22 °C y 32 °C.', '[{"titulo":"Villavicencio, Meta, Colombia - panoramio.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Villavicencio,_Meta,_Colombia_-_panoramio.jpg"},{"titulo":"Villavicencio, Meta, Colombia - panoramio (4).jpg","fuente":"https://commons.wikimedia.org/wiki/File:Villavicencio,_Meta,_Colombia_-_panoramio_(4).jpg"},{"titulo":"Villavicencio, Meta, Colombia - panoramio (2).jpg","fuente":"https://commons.wikimedia.org/wiki/File:Villavicencio,_Meta,_Colombia_-_panoramio_(2).jpg"},{"titulo":"Villavicencio, Meta, Colombia - panoramio (7).jpg","fuente":"https://commons.wikimedia.org/wiki/File:Villavicencio,_Meta,_Colombia_-_panoramio_(7).jpg"},{"titulo":"Villavicencio, Meta, Colombia - panoramio (1).jpg","fuente":"https://commons.wikimedia.org/wiki/File:Villavicencio,_Meta,_Colombia_-_panoramio_(1).jpg"}]'::jsonb, false, 'activo'),
(25, 'Caño Cristales', 'cano-cristales', 'nacional', 'Colombia', 'Llanos Orientales', 'América', 'La Macarena, Meta, Colombia', 'El río de los cinco colores, una joya natural única.', 'Caño Cristales, en la Serranía de La Macarena, se tiñe de rojo, amarillo, verde y otros colores gracias a una planta acuática endémica. Su temporada de visita suele ir de junio a noviembre.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/57/Ca%C3%B1o_Cristales_01.jpg/1920px-Ca%C3%B1o_Cristales_01.jpg', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/5/57/Ca%C3%B1o_Cristales_01.jpg/1920px-Ca%C3%B1o_Cristales_01.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d2/Cascada_los_Cuarzos_-_Ca%C3%B1o_Cristales_-_La_Macarena.jpg/1920px-Cascada_los_Cuarzos_-_Ca%C3%B1o_Cristales_-_La_Macarena.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e7/Cascadas_Manto_de_La_Virgen_-_Ca%C3%B1o_Cristales_-_La_Macarena_-_Meta_-_Colombia.jpg/1920px-Cascadas_Manto_de_La_Virgen_-_Ca%C3%B1o_Cristales_-_La_Macarena_-_Meta_-_Colombia.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9c/Ca%C3%B1o_cristales_la_macarena_Ariari_Meta_Colombia.jpg/1920px-Ca%C3%B1o_cristales_la_macarena_Ariari_Meta_Colombia.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ca/Los_Ocho_en_Ca%C3%B1o_Cristales.jpg/1920px-Los_Ocho_en_Ca%C3%B1o_Cristales.jpg']::text[], array['naturaleza', 'aventura']::text[], array['Caminatas guiadas por el río', 'Baño en pozos autorizados', 'Visita a miradores de La Macarena']::text[], array['Caño Cristales', 'Cristalitos', 'Raudal de Angosturas']::text[], 'Cálido, con temperaturas entre 25 °C y 33 °C.', '[{"titulo":"Caño Cristales 01.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Ca%C3%B1o_Cristales_01.jpg"},{"titulo":"Cascada los Cuarzos - Caño Cristales - La Macarena.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Cascada_los_Cuarzos_-_Ca%C3%B1o_Cristales_-_La_Macarena.jpg"},{"titulo":"Cascadas Manto de La Virgen - Caño Cristales - La Macarena - Meta - Colombia.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Cascadas_Manto_de_La_Virgen_-_Ca%C3%B1o_Cristales_-_La_Macarena_-_Meta_-_Colombia.jpg"},{"titulo":"Caño cristales la macarena Ariari Meta Colombia.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Ca%C3%B1o_cristales_la_macarena_Ariari_Meta_Colombia.jpg"},{"titulo":"Los Ocho en Caño Cristales.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Los_Ocho_en_Ca%C3%B1o_Cristales.jpg"}]'::jsonb, true, 'activo'),
(26, 'México', 'mexico', 'internacional', 'México', 'América', 'América', 'México', 'Cultura milenaria, gastronomía vibrante y playas espectaculares.', 'México sorprende con su diversidad: ruinas mayas y aztecas, ciudades coloniales, una de las gastronomías más reconocidas del mundo y playas en el Caribe y el Pacífico.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/51/Chichen_Itza_3.jpg/1920px-Chichen_Itza_3.jpg', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/5/51/Chichen_Itza_3.jpg/1920px-Chichen_Itza_3.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b9/Chichen_Itza_2.jpg/1920px-Chichen_Itza_2.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f4/Chichen_Itza_1.jpg/1920px-Chichen_Itza_1.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8f/Chichen_Itza_Observatory_2_1.jpg/1920px-Chichen_Itza_Observatory_2_1.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/02/Templo_el_Castillo_-_Chichen_Itza-Yucatan-Mexico0222.jpg/1920px-Templo_el_Castillo_-_Chichen_Itza-Yucatan-Mexico0222.jpg']::text[], array['cultural', 'gastronomia', 'playa']::text[], array['Visita a Chichén Itzá', 'Recorrido por Ciudad de México', 'Teotihuacán', 'Ruta gastronómica']::text[], array['Chichén Itzá', 'Ciudad de México', 'Teotihuacán', 'Oaxaca']::text[], null, '[{"titulo":"Chichen Itza 3.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Chichen_Itza_3.jpg"},{"titulo":"Chichen Itza 2.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Chichen_Itza_2.jpg"},{"titulo":"Chichen Itza 1.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Chichen_Itza_1.jpg"},{"titulo":"Chichen Itza Observatory 2 1.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Chichen_Itza_Observatory_2_1.jpg"},{"titulo":"Templo el Castillo - Chichen Itza-Yucatan-Mexico0222.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Templo_el_Castillo_-_Chichen_Itza-Yucatan-Mexico0222.jpg"}]'::jsonb, true, 'activo'),
(27, 'Cancún', 'cancun', 'internacional', 'México', 'América', 'América', 'Quintana Roo, México', 'Arena blanca, mar turquesa y la Riviera Maya a tus pies.', 'Cancún es uno de los destinos de playa más populares del Caribe. Desde allí se exploran cenotes, parques ecológicos, Isla Mujeres y la Riviera Maya.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d8/Cancun_Strand_Luftbild_%2822143397586%29.jpg/1920px-Cancun_Strand_Luftbild_%2822143397586%29.jpg', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d8/Cancun_Strand_Luftbild_%2822143397586%29.jpg/1920px-Cancun_Strand_Luftbild_%2822143397586%29.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/af/Cancun_Beach.jpg/1920px-Cancun_Beach.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/73/Cancun-beach-Mexico-2016-Luka-Peternel.jpg/1920px-Cancun-beach-Mexico-2016-Luka-Peternel.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c7/At_the_beach_-_Cancun_QR_2020.jpg/1920px-At_the_beach_-_Cancun_QR_2020.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2f/A_beautiful_beach_in_Cancun%2C_Mexico.jpg/1920px-A_beautiful_beach_in_Cancun%2C_Mexico.jpg']::text[], array['playa', 'familiar', 'romantico']::text[], array['Visita a Isla Mujeres', 'Cenotes', 'Parques temáticos', 'Tour a Tulum']::text[], array['Zona Hotelera', 'Isla Mujeres', 'Tulum', 'Playa del Carmen']::text[], 'Cálido tropical, entre 24 °C y 33 °C.', '[{"titulo":"Cancun Strand Luftbild (22143397586).jpg","fuente":"https://commons.wikimedia.org/wiki/File:Cancun_Strand_Luftbild_(22143397586).jpg"},{"titulo":"Cancun Beach.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Cancun_Beach.jpg"},{"titulo":"Cancun-beach-Mexico-2016-Luka-Peternel.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Cancun-beach-Mexico-2016-Luka-Peternel.jpg"},{"titulo":"At the beach - Cancun QR 2020.jpg","fuente":"https://commons.wikimedia.org/wiki/File:At_the_beach_-_Cancun_QR_2020.jpg"},{"titulo":"A beautiful beach in Cancun, Mexico.jpg","fuente":"https://commons.wikimedia.org/wiki/File:A_beautiful_beach_in_Cancun,_Mexico.jpg"}]'::jsonb, true, 'activo'),
(28, 'Punta Cana', 'punta-cana', 'internacional', 'República Dominicana', 'América', 'América', 'La Altagracia, República Dominicana', 'Resorts frente al mar y playas de palmeras infinitas.', 'Punta Cana es sinónimo de descanso: playas de arena blanca, resorts y actividades acuáticas. Es ideal para lunas de miel y vacaciones en familia.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/48/Club_Med_%28Punta_Cana%29.jpg/1920px-Club_Med_%28Punta_Cana%29.jpg', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/4/48/Club_Med_%28Punta_Cana%29.jpg/1920px-Club_Med_%28Punta_Cana%29.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/44/Punta_Cana_Beach_01.jpg/1920px-Punta_Cana_Beach_01.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ee/Punta_Cana_Beach_02.jpg/1920px-Punta_Cana_Beach_02.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d3/Punta_Cana_Beach_03.jpg/1920px-Punta_Cana_Beach_03.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b8/2023_-_Playa_Bavaro_Punta_Cana_-_01.jpg/1920px-2023_-_Playa_Bavaro_Punta_Cana_-_01.jpg']::text[], array['playa', 'romantico', 'familiar']::text[], array['Excursión a Isla Saona', 'Snorkel', 'Paseo en catamarán', 'Descanso en resort']::text[], array['Playa Bávaro', 'Isla Saona', 'Cap Cana', 'Hoyo Azul']::text[], 'Cálido tropical, entre 24 °C y 31 °C.', '[{"titulo":"Club Med (Punta Cana).jpg","fuente":"https://commons.wikimedia.org/wiki/File:Club_Med_(Punta_Cana).jpg"},{"titulo":"Punta Cana Beach 01.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Punta_Cana_Beach_01.jpg"},{"titulo":"Punta Cana Beach 02.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Punta_Cana_Beach_02.jpg"},{"titulo":"Punta Cana Beach 03.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Punta_Cana_Beach_03.jpg"},{"titulo":"2023 - Playa Bavaro Punta Cana - 01.jpg","fuente":"https://commons.wikimedia.org/wiki/File:2023_-_Playa_Bavaro_Punta_Cana_-_01.jpg"}]'::jsonb, true, 'activo'),
(29, 'República Dominicana', 'republica-dominicana', 'internacional', 'República Dominicana', 'América', 'América', 'República Dominicana', 'Historia colonial en Santo Domingo y playas caribeñas.', 'Más allá de sus playas, República Dominicana guarda en Santo Domingo la primera ciudad europea de América, con una Zona Colonial llena de historia, además de paisajes de montaña y ballenas en Samaná.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/46/Calle_las_Damas%2C_Santo_Domingo%2C_Zona_Colonial.jpg/1920px-Calle_las_Damas%2C_Santo_Domingo%2C_Zona_Colonial.jpg', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/4/46/Calle_las_Damas%2C_Santo_Domingo%2C_Zona_Colonial.jpg/1920px-Calle_las_Damas%2C_Santo_Domingo%2C_Zona_Colonial.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/35/Aerial_view_Ciudad_Colonial_Santo_Domingo_09_2019_0067.jpg/1920px-Aerial_view_Ciudad_Colonial_Santo_Domingo_09_2019_0067.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7d/Santo_Domingo_Dominican_Republic_Neighborhoods.jpg/1920px-Santo_Domingo_Dominican_Republic_Neighborhoods.jpg']::text[], array['cultural', 'playa']::text[], array['Recorrido por la Zona Colonial', 'Excursión a Samaná', 'Playas de Bayahíbe']::text[], array['Zona Colonial de Santo Domingo', 'Samaná', 'Bayahíbe', 'Puerto Plata']::text[], null, '[{"titulo":"Calle las Damas, Santo Domingo, Zona Colonial.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Calle_las_Damas,_Santo_Domingo,_Zona_Colonial.jpg"},{"titulo":"Aerial view Ciudad Colonial Santo Domingo 09 2019 0067.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Aerial_view_Ciudad_Colonial_Santo_Domingo_09_2019_0067.jpg"},{"titulo":"Santo Domingo Dominican Republic Neighborhoods.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Santo_Domingo_Dominican_Republic_Neighborhoods.jpg"}]'::jsonb, false, 'activo'),
(30, 'Panamá', 'panama', 'internacional', 'Panamá', 'América', 'América', 'Panamá', 'Rascacielos, el Canal de Panamá e islas paradisíacas.', 'Panamá combina una capital moderna con el histórico Casco Antiguo, el famoso Canal y destinos de playa como San Blas y Bocas del Toro.', 'https://upload.wikimedia.org/wikipedia/commons/c/c3/Panama_City_Skyline_2015.jpg_unscaled', array['https://upload.wikimedia.org/wikipedia/commons/c/c3/Panama_City_Skyline_2015.jpg_unscaled', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d1/Panama_City_Skyline_1.jpg/1920px-Panama_City_Skyline_1.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5f/Skyline_of_Panama_City_01.jpg/1920px-Skyline_of_Panama_City_01.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/00/Panama_City_skyline_08_2013_panorama_7058.JPG/1920px-Panama_City_skyline_08_2013_panorama_7058.JPG']::text[], array['ciudad', 'playa', 'cultural']::text[], array['Visita al Canal de Panamá (Miraflores)', 'Recorrido por el Casco Antiguo', 'Excursión a San Blas']::text[], array['Canal de Panamá', 'Casco Antiguo', 'Cinta Costera', 'Islas de San Blas']::text[], null, '[{"titulo":"Panama City Skyline 2015.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Panama_City_Skyline_2015.jpg"},{"titulo":"Panama City Skyline 1.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Panama_City_Skyline_1.jpg"},{"titulo":"Skyline of Panama City 01.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Skyline_of_Panama_City_01.jpg"},{"titulo":"Panama City skyline 08 2013 panorama 7058.JPG","fuente":"https://commons.wikimedia.org/wiki/File:Panama_City_skyline_08_2013_panorama_7058.JPG"}]'::jsonb, false, 'activo'),
(31, 'Estados Unidos', 'estados-unidos', 'internacional', 'Estados Unidos', 'América', 'América', 'Estados Unidos', 'Ciudades icónicas, parques nacionales y entretenimiento.', 'Estados Unidos ofrece experiencias para todos: la energía de Nueva York, las playas de Miami, los parques temáticos de Orlando y parques nacionales impresionantes.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7a/View_of_Empire_State_Building_from_Rockefeller_Center_New_York_City_dllu_%28cropped%29.jpg/1920px-View_of_Empire_State_Building_from_Rockefeller_Center_New_York_City_dllu_%28cropped%29.jpg', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7a/View_of_Empire_State_Building_from_Rockefeller_Center_New_York_City_dllu_%28cropped%29.jpg/1920px-View_of_Empire_State_Building_from_Rockefeller_Center_New_York_City_dllu_%28cropped%29.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5f/Manhattan_from_Weehawken%2C_NJ.jpg/1920px-Manhattan_from_Weehawken%2C_NJ.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/ba/Lower_Manhattan_from_Jersey_City_September_2020_panorama.jpg/1920px-Lower_Manhattan_from_Jersey_City_September_2020_panorama.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f0/Brooklyn_Bridge_and_the_Lower_Manhattan_skyline_from_Pebble_Beach%2C_New_York.jpg/1920px-Brooklyn_Bridge_and_the_Lower_Manhattan_skyline_from_Pebble_Beach%2C_New_York.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/41/Lower_Manhattan_from_Jersey_City_November_2014_panorama_2.jpg/1920px-Lower_Manhattan_from_Jersey_City_November_2014_panorama_2.jpg']::text[], array['ciudad', 'cultural', 'familiar']::text[], array['Recorrido por Nueva York', 'Compras', 'Parques temáticos', 'Parques nacionales']::text[], array['Nueva York', 'Miami', 'Los Ángeles', 'Las Vegas']::text[], null, '[{"titulo":"View of Empire State Building from Rockefeller Center New York City dllu (cropped).jpg","fuente":"https://commons.wikimedia.org/wiki/File:View_of_Empire_State_Building_from_Rockefeller_Center_New_York_City_dllu_(cropped).jpg"},{"titulo":"Manhattan from Weehawken, NJ.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Manhattan_from_Weehawken,_NJ.jpg"},{"titulo":"Lower Manhattan from Jersey City September 2020 panorama.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Lower_Manhattan_from_Jersey_City_September_2020_panorama.jpg"},{"titulo":"Brooklyn Bridge and the Lower Manhattan skyline from Pebble Beach, New York.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Brooklyn_Bridge_and_the_Lower_Manhattan_skyline_from_Pebble_Beach,_New_York.jpg"},{"titulo":"Lower Manhattan from Jersey City November 2014 panorama 2.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Lower_Manhattan_from_Jersey_City_November_2014_panorama_2.jpg"}]'::jsonb, false, 'activo'),
(32, 'Orlando', 'orlando', 'internacional', 'Estados Unidos', 'América', 'América', 'Florida, Estados Unidos', 'La capital mundial de los parques temáticos.', 'Orlando es el destino soñado para viajar en familia, con parques temáticos de fama mundial, parques acuáticos y zonas de compras.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e8/Orlando%2C_Florida_%28cropped%29.jpg/1920px-Orlando%2C_Florida_%28cropped%29.jpg', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e8/Orlando%2C_Florida_%28cropped%29.jpg/1920px-Orlando%2C_Florida_%28cropped%29.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5f/Lake-eola-park-orlando-florida.jpg/1920px-Lake-eola-park-orlando-florida.jpg']::text[], array['familiar']::text[], array['Parques temáticos', 'Parques acuáticos', 'Compras en outlets', 'Kennedy Space Center']::text[], array['Parques temáticos', 'Disney Springs', 'Kennedy Space Center', 'International Drive']::text[], null, '[{"titulo":"Orlando, Florida (cropped).jpg","fuente":"https://commons.wikimedia.org/wiki/File:Orlando,_Florida_(cropped).jpg"},{"titulo":"Lake-eola-park-orlando-florida.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Lake-eola-park-orlando-florida.jpg"}]'::jsonb, true, 'activo'),
(33, 'Perú', 'peru', 'internacional', 'Perú', 'América', 'América', 'Perú', 'Machu Picchu, los Andes y una gastronomía reconocida mundialmente.', 'Perú es historia viva: la ciudadela inca de Machu Picchu, el Valle Sagrado y Cusco, junto con Lima, una de las capitales gastronómicas de América.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bb/Machu_Picchu%2C_2023_%28012%29.jpg/1920px-Machu_Picchu%2C_2023_%28012%29.jpg', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bb/Machu_Picchu%2C_2023_%28012%29.jpg/1920px-Machu_Picchu%2C_2023_%28012%29.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/71/Machu_Picchu%2C_Per%C3%BA%2C_2015-07-30%2C_DD_47.JPG/1920px-Machu_Picchu%2C_Per%C3%BA%2C_2015-07-30%2C_DD_47.JPG', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/02/Machu_Picchu%2C_Per%C3%BA%2C_2015-07-30%2C_DD_60.JPG/1920px-Machu_Picchu%2C_Per%C3%BA%2C_2015-07-30%2C_DD_60.JPG', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9f/99_-_Machu_Picchu_-_Juin_2009.edit3.jpg/1920px-99_-_Machu_Picchu_-_Juin_2009.edit3.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a8/99_-_Machu_Picchu_-_Juin_2009.jpg/1920px-99_-_Machu_Picchu_-_Juin_2009.jpg']::text[], array['cultural', 'aventura', 'gastronomia']::text[], array['Visita a Machu Picchu', 'Recorrido por el Valle Sagrado', 'Tour gastronómico en Lima', 'Montaña de Colores']::text[], array['Machu Picchu', 'Cusco', 'Valle Sagrado', 'Lima']::text[], null, '[{"titulo":"Machu Picchu, 2023 (012).jpg","fuente":"https://commons.wikimedia.org/wiki/File:Machu_Picchu,_2023_(012).jpg"},{"titulo":"Machu Picchu, Perú, 2015-07-30, DD 47.JPG","fuente":"https://commons.wikimedia.org/wiki/File:Machu_Picchu,_Per%C3%BA,_2015-07-30,_DD_47.JPG"},{"titulo":"Machu Picchu, Perú, 2015-07-30, DD 60.JPG","fuente":"https://commons.wikimedia.org/wiki/File:Machu_Picchu,_Per%C3%BA,_2015-07-30,_DD_60.JPG"},{"titulo":"99 - Machu Picchu - Juin 2009.edit3.jpg","fuente":"https://commons.wikimedia.org/wiki/File:99_-_Machu_Picchu_-_Juin_2009.edit3.jpg"},{"titulo":"99 - Machu Picchu - Juin 2009.jpg","fuente":"https://commons.wikimedia.org/wiki/File:99_-_Machu_Picchu_-_Juin_2009.jpg"}]'::jsonb, true, 'activo'),
(34, 'Argentina', 'argentina', 'internacional', 'Argentina', 'América', 'América', 'Argentina', 'Tango en Buenos Aires, glaciares en la Patagonia y vinos en Mendoza.', 'Argentina ofrece contrastes extraordinarios: la vida cultural de Buenos Aires, los glaciares de la Patagonia, las Cataratas del Iguazú y los viñedos de Mendoza.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c8/Perito_Moreno_Glacier_2023.jpg/1920px-Perito_Moreno_Glacier_2023.jpg', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c8/Perito_Moreno_Glacier_2023.jpg/1920px-Perito_Moreno_Glacier_2023.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/64/Obelisco_de_Buenos_Aires_at_sunset.jpg/1920px-Obelisco_de_Buenos_Aires_at_sunset.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6b/Panorama_Obelisco_de_Buenos_Aires_2019.jpg/1920px-Panorama_Obelisco_de_Buenos_Aires_2019.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/15/ObeliscoBA2015.jpg/1920px-ObeliscoBA2015.jpg']::text[], array['naturaleza', 'cultural', 'gastronomia']::text[], array['Show de tango', 'Glaciar Perito Moreno', 'Cataratas del Iguazú', 'Ruta del vino en Mendoza']::text[], array['Buenos Aires', 'El Calafate', 'Iguazú', 'Mendoza', 'Bariloche']::text[], null, '[{"titulo":"Perito Moreno Glacier 2023.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Perito_Moreno_Glacier_2023.jpg"},{"titulo":"Obelisco de Buenos Aires at sunset.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Obelisco_de_Buenos_Aires_at_sunset.jpg"},{"titulo":"Panorama Obelisco de Buenos Aires 2019.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Panorama_Obelisco_de_Buenos_Aires_2019.jpg"},{"titulo":"ObeliscoBA2015.jpg","fuente":"https://commons.wikimedia.org/wiki/File:ObeliscoBA2015.jpg"}]'::jsonb, false, 'activo'),
(35, 'Brasil', 'brasil', 'internacional', 'Brasil', 'América', 'América', 'Brasil', 'Playas, samba y paisajes inolvidables.', 'Brasil es alegría y naturaleza: Río de Janeiro con el Cristo Redentor y el Pan de Azúcar, playas del nordeste y la inmensidad de sus paisajes.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/98/Cidade_Maravilhosa.jpg/1920px-Cidade_Maravilhosa.jpg', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/9/98/Cidade_Maravilhosa.jpg/1920px-Cidade_Maravilhosa.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ed/Sugarloaf_Cable_Car_viewed_from_Rio_de_Janeiro%2C_Brazil.jpg/1920px-Sugarloaf_Cable_Car_viewed_from_Rio_de_Janeiro%2C_Brazil.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/04/Rio_de_Janeiro_skyline_and_Sugarloaf_Mountain_at_sunset%2C_Brazil_3.jpg/1920px-Rio_de_Janeiro_skyline_and_Sugarloaf_Mountain_at_sunset%2C_Brazil_3.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/30/Rio_skyline_and_Cristo_Redentor_from_Sugarloaf_Mountain%2C_Brazil.jpg/1920px-Rio_skyline_and_Cristo_Redentor_from_Sugarloaf_Mountain%2C_Brazil.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b2/Sugarloaf_Sunrise_2.jpg/1920px-Sugarloaf_Sunrise_2.jpg']::text[], array['playa', 'ciudad', 'cultural']::text[], array['Cristo Redentor', 'Pan de Azúcar', 'Playas de Copacabana e Ipanema', 'Cataratas del Iguazú (lado brasileño)']::text[], array['Río de Janeiro', 'Salvador de Bahía', 'Florianópolis', 'Foz do Iguaçu']::text[], null, '[{"titulo":"Cidade Maravilhosa.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Cidade_Maravilhosa.jpg"},{"titulo":"Sugarloaf Cable Car viewed from Rio de Janeiro, Brazil.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Sugarloaf_Cable_Car_viewed_from_Rio_de_Janeiro,_Brazil.jpg"},{"titulo":"Rio de Janeiro skyline and Sugarloaf Mountain at sunset, Brazil 3.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Rio_de_Janeiro_skyline_and_Sugarloaf_Mountain_at_sunset,_Brazil_3.jpg"},{"titulo":"Rio skyline and Cristo Redentor from Sugarloaf Mountain, Brazil.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Rio_skyline_and_Cristo_Redentor_from_Sugarloaf_Mountain,_Brazil.jpg"},{"titulo":"Sugarloaf Sunrise 2.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Sugarloaf_Sunrise_2.jpg"}]'::jsonb, false, 'activo'),
(36, 'España', 'espana', 'internacional', 'España', 'Europa', 'Europa', 'España', 'Arte, historia y gastronomía en cada ciudad.', 'España combina ciudades llenas de vida como Madrid y Barcelona con el encanto andaluz de Sevilla y Granada, además de playas mediterráneas y una gastronomía única.', 'https://upload.wikimedia.org/wikipedia/commons/e/ef/SF_maig_2_cropped.jpg_unscaled', array['https://upload.wikimedia.org/wikipedia/commons/e/ef/SF_maig_2_cropped.jpg_unscaled', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a1/Madrid_-_Edificio_Grassy_%28Gran_V%C3%ADa_1%29_-_north_facade_-_relief_over_entrance.jpg/1920px-Madrid_-_Edificio_Grassy_%28Gran_V%C3%ADa_1%29_-_north_facade_-_relief_over_entrance.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/92/Gran_V%C3%ADa_%28Madrid%29_1.jpg/1920px-Gran_V%C3%ADa_%28Madrid%29_1.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/30/Gran_Via_Madrid_December_2023_03.jpg/1920px-Gran_Via_Madrid_December_2023_03.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4f/Gran_V%C3%ADa_%28Madrid%29_42.jpg/1920px-Gran_V%C3%ADa_%28Madrid%29_42.jpg']::text[], array['cultural', 'ciudad', 'gastronomia']::text[], array['Sagrada Familia en Barcelona', 'Museo del Prado en Madrid', 'Alhambra de Granada', 'Ruta de tapas']::text[], array['Madrid', 'Barcelona', 'Sevilla', 'Granada', 'Valencia']::text[], null, '[{"titulo":"SF maig 2 cropped.jpg","fuente":"https://commons.wikimedia.org/wiki/File:SF_maig_2_cropped.jpg"},{"titulo":"Madrid - Edificio Grassy (Gran Vía 1) - north facade - relief over entrance.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Madrid_-_Edificio_Grassy_(Gran_V%C3%ADa_1)_-_north_facade_-_relief_over_entrance.jpg"},{"titulo":"Gran Vía (Madrid) 1.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Gran_V%C3%ADa_(Madrid)_1.jpg"},{"titulo":"Gran Via Madrid December 2023 03.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Gran_Via_Madrid_December_2023_03.jpg"},{"titulo":"Gran Vía (Madrid) 42.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Gran_V%C3%ADa_(Madrid)_42.jpg"}]'::jsonb, true, 'activo'),
(37, 'Francia', 'francia', 'internacional', 'Francia', 'Europa', 'Europa', 'Francia', 'París, la Costa Azul y castillos de cuento.', 'Francia es uno de los destinos más visitados del mundo. París enamora con la Torre Eiffel y el Louvre, mientras regiones como la Provenza y la Costa Azul ofrecen paisajes inolvidables.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/85/Tour_Eiffel_Wikimedia_Commons_%28cropped%29.jpg/1920px-Tour_Eiffel_Wikimedia_Commons_%28cropped%29.jpg', array['https://thumb.wikimedia.org/wikipedia/commons/thumb/8/85/Tour_Eiffel_Wikimedia_Commons_%28cropped%29.jpg/1920px-Tour_Eiffel_Wikimedia_Commons_%28cropped%29.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/60/Seine_Pont_Royal_Louvre_Paris.jpg/1920px-Seine_Pont_Royal_Louvre_Paris.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e5/Seine_wide.jpg/1920px-Seine_wide.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ca/Port_Debilly_in_Paris_001.JPG/1920px-Port_Debilly_in_Paris_001.JPG', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e7/Front_de_Seine_as_seen_from_Pont_Mirabeau_140412_1.jpg/1920px-Front_de_Seine_as_seen_from_Pont_Mirabeau_140412_1.jpg']::text[], array['romantico', 'cultural', 'ciudad']::text[], array['Torre Eiffel', 'Museo del Louvre', 'Crucero por el Sena', 'Palacio de Versalles']::text[], array['París', 'Versalles', 'Niza', 'Mont-Saint-Michel']::text[], null, '[{"titulo":"Tour Eiffel Wikimedia Commons (cropped).jpg","fuente":"https://commons.wikimedia.org/wiki/File:Tour_Eiffel_Wikimedia_Commons_(cropped).jpg"},{"titulo":"Seine Pont Royal Louvre Paris.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Seine_Pont_Royal_Louvre_Paris.jpg"},{"titulo":"Seine wide.jpg","fuente":"https://commons.wikimedia.org/wiki/File:Seine_wide.jpg"},{"titulo":"Port Debilly in Paris 001.JPG","fuente":"https://commons.wikimedia.org/wiki/File:Port_Debilly_in_Paris_001.JPG"},{"titulo":"Front de Seine as seen from Pont Mirabeau 140412 1.jpg","fuente":"h